create table if not exists rooted_in_christ.programmes (id uuid primary key default gen_random_uuid(), title text not null, slug text not null unique, description text, category text, status rooted_in_christ.record_status not null default 'draft', created_by uuid references auth.users(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists rooted_in_christ.projects (id uuid primary key default gen_random_uuid(), title text not null, slug text not null unique, description text, location text, status rooted_in_christ.record_status not null default 'draft', created_by uuid references auth.users(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists rooted_in_christ.events (id uuid primary key default gen_random_uuid(), title text not null, description text, start_at timestamptz not null, status rooted_in_christ.record_status not null default 'draft', created_by uuid references auth.users(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
alter table rooted_in_christ.programmes enable row level security;
alter table rooted_in_christ.projects enable row level security;
alter table rooted_in_christ.events enable row level security;
drop policy if exists "ministry editors manage programmes" on rooted_in_christ.programmes;
drop policy if exists "ministry editors manage projects" on rooted_in_christ.projects;
drop policy if exists "ministry editors manage events" on rooted_in_christ.events;
create policy "active members manage programmes" on rooted_in_christ.programmes for all to authenticated using (rooted_in_christ.has_role('ministry_admin') or rooted_in_christ.has_role('editor')) with check (rooted_in_christ.has_role('ministry_admin') or rooted_in_christ.has_role('editor'));
create policy "active members manage projects" on rooted_in_christ.projects for all to authenticated using (rooted_in_christ.has_role('ministry_admin') or rooted_in_christ.has_role('editor')) with check (rooted_in_christ.has_role('ministry_admin') or rooted_in_christ.has_role('editor'));
create policy "active members manage events" on rooted_in_christ.events for all to authenticated using (rooted_in_christ.has_role('ministry_admin') or rooted_in_christ.has_role('editor')) with check (rooted_in_christ.has_role('ministry_admin') or rooted_in_christ.has_role('editor'));
